// The tokenizer is the one place in arca where being subtly wrong is worse
// than crashing: a divergence produces vectors that no longer sit next to the
// ones already in the index, and nothing reports it. So there are two layers
// here — a synthetic vocabulary that pins each rule on its own, and ids
// captured from @huggingface/transformers before it was removed, which is the
// implementation that actually built the index.
import { test } from 'node:test';
import assert from 'node:assert';
import fs from 'node:fs';
import path from 'node:path';
import { loadTokenizer } from './tokenizer.js';
import { modelDir } from './model.js';

// [PAD]=0 [UNK]=1 [CLS]=2 [SEP]=3, then whatever a case needs.
function toy(words) {
  const vocab = { '[PAD]': 0, '[UNK]': 1, '[CLS]': 2, '[SEP]': 3 };
  words.forEach((w, i) => { vocab[w] = 4 + i; });
  return loadTokenizer({ model: { vocab } });
}

const BACKSLASH = String.fromCharCode(92);
const TAB = String.fromCharCode(9);
const NEWLINE = String.fromCharCode(10);

test('punctuation is split off as its own token', () => {
  const t = toy(['a', 'b']);
  assert.deepEqual(t.encode('a,b'), [2, 4, 1, 5, 3]);
});

test('a backslash is punctuation, not a word character', () => {
  // It is not in the Unicode P category — HuggingFace adds the ASCII ranges
  // that cover it. Getting this wrong made a regex escape tokenize as one
  // word, and was invisible to every test that contained no regex.
  const t = toy(['s']);
  assert.deepEqual(t.encode(BACKSLASH + 's'), [2, 1, 4, 3]);
});

test('accents are stripped and text is lowercased', () => {
  const t = toy(['cafe']);
  assert.deepEqual(t.encode('CAFÉ'), [2, 4, 3]);
});

test('Cyrillic yo and short-i lose their diacritic', () => {
  // A consequence of strip_accents, not a mistake: the index was built so.
  const t = toy(['еж', 'иод']);
  assert.deepEqual(t.encode('ёж'), [2, 4, 3], 'yo folds to ye');
  assert.deepEqual(t.encode('йод'), [2, 5, 3], 'short i folds to i');
});

test('CJK characters are separated into individual words', () => {
  const t = toy(['中', '文']);
  assert.deepEqual(t.encode('中文'), [2, 4, 5, 3]);
});

test('subwords after the first carry the ## prefix', () => {
  const t = toy(['play', '##ing']);
  assert.deepEqual(t.encode('playing'), [2, 4, 5, 3]);
});

test('a word with any unmatchable piece is [UNK] whole', () => {
  const t = toy(['play']);
  assert.deepEqual(t.encode('playing'), [2, 1, 3], 'partial matches must not leak through');
});

test('words longer than 100 characters are [UNK]', () => {
  const t = toy(['x', '##x']);
  assert.deepEqual(t.encode('x'.repeat(101)), [2, 1, 3]);
  assert.equal(t.encode('x'.repeat(100)).length, 102, '100 is still tokenized');
});

test('a vocabulary lookup cannot hit Object.prototype', () => {
  const t = toy(['a']);
  for (const word of ['constructor', 'tostring', 'valueof']) {
    assert.deepEqual(t.encode(word), [2, 1, 3], `${word} must be [UNK], not a function`);
  }
});

test('filling the window drops [SEP] rather than the last word', () => {
  // transformers.js truncates after the template has added the special tokens,
  // by slicing. Reproducing that is what keeps a long exchange comparable to
  // the vector already stored for it.
  const t = toy(['w']);
  const ids = t.encode(Array(600).fill('w').join(' '));
  assert.equal(ids.length, 512);
  assert.equal(ids[0], 2, 'still starts with [CLS]');
  assert.notEqual(ids[511], 3, '[SEP] is the token that gets cut');
});

test('empty and whitespace-only input is just the special tokens', () => {
  const t = toy(['a']);
  assert.deepEqual(t.encode(''), [2, 3]);
  assert.deepEqual(t.encode('  ' + TAB + NEWLINE + ' '), [2, 3]);
});

