test('matches transformers.js on the real vocabulary', (t) => {
  const file = path.join(modelDir(), 'tokenizer.json');
  if (!fs.existsSync(file)) {
    t.skip('model not fetched here; the synthetic cases above still ran');
    return;
  }
  const tok = loadTokenizer(JSON.parse(fs.readFileSync(file, 'utf8')));
  for (const [name, { text, ids }] of Object.entries(FIXTURES)) {
    assert.deepEqual(tok.encode(text), ids, `diverged on "${name}"`);
  }
});
